const pedidos = [
  { id: 1, cliente: 'Ana', total: 120, pago: true },
  { id: 2, cliente: 'Bruno', total: 80, pago: false },
  { id: 3, cliente: 'Carla', total: 250, pago: true }
];

// 1. Filtra apenas pedidos pagos
const pagos = pedidos.filter((p) => p.pago);

// 2. Extrai somente os nomes
const nomesPagantes = pagos.map((p) => p.cliente);

// 3. Soma o faturamento confirmado
const faturamento = pagos.reduce((soma, p) => soma + p.total, 0);

console.log('Pagantes:', nomesPagantes);
console.log('Faturamento total: R$', faturamento);
